import numpy as np
def rd(f):
    L=open(f).read().split('\n')[2:]
    sym=[];pos=[]
    for l in L:
        if l.strip():
            p=l.split(); sym.append(p[0]); pos.append([float(x) for x in p[1:4]])
    return sym,np.array(pos)
sym,pos=rd('opt1.xyz')
ir=sym.index('Ir')
for i in [1,2,4,6,8,11,44,23,47]:
    print(i,sym[i],round(np.linalg.norm(pos[i]-pos[ir]),2))
